fun main() {
    val r = Regex("(\\d+)-(\\w+)")
    val m = r.find("order 12-abc and 7-x")
    println(m?.value)
    println(m?.groupValues)
    println(m?.groups?.get(2)?.value)
    println(r.findAll("1-a 22-bb 333-ccc").map { it.groupValues[1].toInt() }.toList())
    println(r.replace("1-a 22-bb") { "<${it.groupValues[2]}>" })
    println("a1b22c333".replace(Regex("[0-9]+"), "#"))
    println(Regex("^[a-z]+$").matches("hello"))
    println("x@y.com".matches(Regex("\\w+@\\w+\\.com")))
    println("a,b;c d".split(Regex("[,; ]")))
    println(Regex("o").containsMatchIn("foo"))
    println("2024-05-17".split("-").map { it.toInt() })
    val named = Regex("(?<year>\\d{4})-(?<mon>\\d{2})")
    val nm = named.matchEntire("2024-05")
    println(nm?.groups?.get("year")?.value + "/" + nm?.groups?.get("mon")?.value)
    println(Regex("a+").find("baaac")?.range)
    println("hello world".replaceFirst(Regex("o"), "0"))
    println(Regex("\\s+").split("a   b \t c"))
    println("Hello".lowercase().contains(Regex("ell")))
    println("abc".toRegex().pattern)
    println(Regex("(a)(b)?").find("a")?.groupValues)
    println("CamelCaseString".replace(Regex("([A-Z])")) { "_" + it.value.lowercase() }.trimStart('_'))
}
